import{_ as s,o as e,c as i,a2 as a}from"./chunks/framework.DTdEDYjJ.js";const k=JSON.parse('{"title":"参与开发","description":"","frontmatter":{},"headers":[],"relativePath":"development/contributing.md","filePath":"development/contributing.md"}'),n={name:"development/contributing.md"};function d(p,t,h,o,r,l){return e(),i("div",null,[...t[0]||(t[0]=[a(`<h1 id="参与开发" tabindex="-1">参与开发 <a class="header-anchor" href="#参与开发" aria-label="Permalink to &quot;参与开发&quot;">​</a></h1><p>当前文档面向OpenBot0.10.9源码预览。本页面向已取得源码的协作者：先在独立数据目录运行，再用与改动相关的验证说明行为变化。</p><h2 id="准备开发环境" tabindex="-1">准备开发环境 <a class="header-anchor" href="#准备开发环境" aria-label="Permalink to &quot;准备开发环境&quot;">​</a></h2><p>桌面开发需要 Mac arm64、Node.js 22.19.0 或更新版本与 npm。本机浏览器验收还需 Chrome/Chromium；Linux Node 不需要 Electron，部署前提另见<a href="/openbot/deployment/self-host.html">自建节点</a>。</p><p>在仓库根目录执行：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OPENBOT_USERDATA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/Library/Application Support/openbot-dev&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>开发目录放在仓库外，不使用日常安装的数据、登录状态和模型凭据。<code>npm ci</code> 按根目录锁文件安装；不要为验证文档去升级运行时依赖。</p><h2 id="先找现有入口" tabindex="-1">先找现有入口 <a class="header-anchor" href="#先找现有入口" aria-label="Permalink to &quot;先找现有入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>修改范围</th><th>先阅读的仓库文件</th></tr></thead><tbody><tr><td>模型连接与解析</td><td><code>src/config.js</code>、<code>main.js</code>、<code>node/execution.js</code></td></tr><tr><td>Agent 执行内核</td><td><code>src/agent-driver.js</code>、<code>src/dsh-agent.js</code>、<code>src/pi-agent.js</code>、<code>src/tools.js</code></td></tr><tr><td>浏览器与控制权</td><td><code>src/screen.js</code>、<code>src/screen-driver.js</code></td></tr><tr><td>Node 执行</td><td><code>node/execution.js</code>、<code>src/remote-execution.js</code></td></tr><tr><td>Linux 容器</td><td><code>deploy/node/Dockerfile</code>、<code>run-container.sh</code>、<code>entrypoint.sh</code></td></tr><tr><td>数据与交付</td><td><code>src/persistence.js</code>、<code>docs/upgrading.md</code>、<code>releases/manifest.json</code></td></tr></tbody></table><p>模型、Harness、执行主机与屏幕通过薄 Adapter 接入。Bot 身份、记忆、审批、动作预算和持久记录继续归 OpenBot；新增 Adapter 不另建权限状态、恢复队列或未知结果自动重试路径。</p><h2 id="将改动限制在一个问题" tabindex="-1">将改动限制在一个问题 <a class="header-anchor" href="#将改动限制在一个问题" aria-label="Permalink to &quot;将改动限制在一个问题&quot;">​</a></h2><p>先描述具体触发条件和预期结果，再复用已有实现。新增功能要同时说明它在哪个执行位置生效、需要什么授权、如何停止，以及结果不确定时如何呈现。</p><p>涉及输入、审批、预算、任务归属或持久化的修改，应保留失败记录和最小复现。仅修改文档或文案时，不必为重复实现断言新增测试。</p><h2 id="按范围验证" tabindex="-1">按范围验证 <a class="header-anchor" href="#按范围验证" aria-label="Permalink to &quot;按范围验证&quot;">​</a></h2><table tabindex="0"><thead><tr><th>范围</th><th>命令</th><th>验证重点</th></tr></thead><tbody><tr><td>逻辑与策略</td><td><code>npm test</code></td><td>故障复现、取消、归属与契约</td></tr><tr><td>桌面 Web 界面</td><td><code>npm run test:web</code></td><td>普通和窄窗口、真实浏览器</td></tr><tr><td>原生浏览器</td><td><code>npm run test:computer-use</code></td><td>多屏、审批、输入与接管</td></tr><tr><td>动作预算</td><td><code>npm run test:action-budget</code></td><td>额度与未知副作用</td></tr><tr><td>观察顺序</td><td><code>npm run test:observation</code></td><td>新画面、失败后阻止盲操作</td></tr><tr><td>启动与数据迁移</td><td><code>npm run test:upgrade</code></td><td>旧身份、数据保留与中断恢复</td></tr><tr><td>Node 协议与浏览器</td><td><code>npm run test:node-execution</code>、<code>npm run test:node-browser</code></td><td>节点任务与窗口适配</td></tr></tbody></table><p>Web 测试必要时用 <code>OPENBOT_CHROME_PATH</code> 指定浏览器可执行文件。Fleet 原生验收另需仓库外的脱敏 <code>fleet.manifest.json</code>，由 <code>OPENBOT_E2E_MANIFEST</code> 指定；缺少样本不能算通过，普通 <code>npm test</code> 和启动不依赖它。</p><h2 id="验证最终安装包" tabindex="-1">验证最终安装包 <a class="header-anchor" href="#验证最终安装包" aria-label="Permalink to &quot;验证最终安装包&quot;">​</a></h2><p>改变发布运行路径时，制作安装包并检查实际产物：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:mac</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:release</span></span></code></pre></div><p>产物位于 <code>dist/</code>，实际 <code>.app</code> 路径记录于 <code>dist/.last-app-path</code>。若重新生成图标，需要带 Pillow 的 Python，可通过 <code>OPENBOT_PYTHON</code> 指定解释器。</p><p>对最终包做升级检查时，显式指定其可执行文件；将下方路径替换为实际包路径：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OPENBOT_E2E_APP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/path/to/OpenBot.app/Contents/MacOS/OpenBot&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:upgrade</span></span></code></pre></div><p>未指定时验证源码 Electron，不能替代最终包。可以用 <code>OPENBOT_E2E_OUT</code> 指定新证据目录，避免覆盖先前失败记录。</p><h2 id="文档站开发" tabindex="-1">文档站开发 <a class="header-anchor" href="#文档站开发" aria-label="Permalink to &quot;文档站开发&quot;">​</a></h2><p>文档站使用 <code>website/</code> 下独立的 VitePress 工程。从仓库根目录执行：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> website</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> website</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> website</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> website</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:artifact</span></span></code></pre></div><p>同一份website源码用于wave和GitHub项目Pages；发布base均为<code>/openbot/</code>，不维护第二套正文。Pages只使用仓库内的构建产物和OIDC，无需云SSH或模型凭据。</p><p>正文使用标准 Markdown，站内链接指向已存在路由。仓库源码路径使用行内代码，避免把仓库文件当作文档站可访问页面。版本和支持能力以实际发布证据为准。</p><h2 id="提交说明与凭据处理" tabindex="-1">提交说明与凭据处理 <a class="header-anchor" href="#提交说明与凭据处理" aria-label="Permalink to &quot;提交说明与凭据处理&quot;">​</a></h2><p>说明触发条件、修改后的行为、运行过的检查及未运行项。分开记录源码、Web、最终 App、受控夹具和真实模型结果；付费测试单独明确运行，不自动重跑来替换失败。</p><p>问题报告应包含版本、系统、模型/Harness 类型、最小步骤和脱敏错误。Key、Token、私人对话及浏览器资料不进入提交、截图、日志或问题描述。</p><p>新增依赖时更新锁文件并记录上游来源、固定版本和许可，按实际引入内容维护 <code>THIRD_PARTY_LICENSES.txt</code>。本地Git交付、远端代码、Pages站点和安装包各自登记，不把本地标签或Actions构建等同公网发布。</p><p>文档部署机制见<a href="https://vitepress.dev/guide/deploy#github-pages" target="_blank" rel="noreferrer">VitePress官方指南</a>和<a href="https://docs.github.com/en/pages/getting-started-with-github-pages/using-custom-workflows-with-github-pages" target="_blank" rel="noreferrer">GitHub Pages官方指南</a>。</p><p>相邻页面：<a href="/openbot/guide/quickstart.html">快速开始</a>、<a href="/openbot/concepts/architecture.html">架构</a>、<a href="/openbot/development/changelog.html">变更记录</a>。</p>`,34)])])}const F=s(n,[["render",d]]);export{k as __pageData,F as default};
